package netcheck

import (
	"context"
	"crypto/tls"
	"net"
	"net/http"
	"runtime"
	"time"

	probing "github.com/prometheus-community/pro-bing"
)

// Timeouts and counts are named constants, not configuration. Every scalar
// added to the config is a row in configuration/fields.go and its tests; these
// become settings when someone asks for them, not before.
const (
	resolveTimeout = 5 * time.Second
	dialTimeout    = 5 * time.Second
	tlsTimeout     = 8 * time.Second
	httpTimeout    = 8 * time.Second
	pingTimeout    = 4 * time.Second
	pingCount      = 3

	// expiryWarnWindow is how close a certificate may come to expiring before
	// the check warns. Thirty days is a renewal cycle: past it, nobody has
	// started renewing yet, so warning earlier is noise.
	expiryWarnWindow = 30 * 24 * time.Hour
)

// PingStats is what one ICMP probe run observed.
type PingStats struct {
	Sent     int
	Received int
	AvgRTT   time.Duration
}

// HTTPResult is what one HEAD request observed.
type HTTPResult struct {
	Status int
	Server string
	// TLS reports whether the request was made over TLS, so the check can say
	// which scheme it actually spoke rather than which one was intended.
	TLS bool
}

// Env is the seam every stage reaches the network through.
//
// internal/docker's dockerRunner is the precedent, with one difference: that
// one is a package-level var tests swap, which forces those tests to run
// serially. Here the seam is a parameter, so a fake is per-call and the
// package stays safe to use concurrently.
type Env interface {
	// Resolve returns the addresses host maps to. resolver is a nameserver
	// ("host" or "host:port"); empty means the system resolver.
	Resolve(ctx context.Context, host, resolver string) ([]net.IP, error)
	// ReverseLookup returns the names ip maps back to.
	ReverseLookup(ctx context.Context, ip, resolver string) ([]string, error)
	// Ping sends count ICMP echo requests.
	Ping(ctx context.Context, host string, count int) (PingStats, error)
	// DialTCP opens and immediately closes a TCP connection, reporting how
	// long the handshake took. It returns no connection: the stage wants to
	// know whether the port answers, and handing back a Conn would make every
	// fake responsible for closing it.
	DialTCP(ctx context.Context, addr string) (time.Duration, error)
	// Handshake completes a TLS handshake without verifying the chain.
	Handshake(ctx context.Context, addr, serverName string) (*tls.ConnectionState, error)
	// Head issues an HTTP HEAD request.
	Head(ctx context.Context, url string) (HTTPResult, error)
	// Now is the clock, injected so an expiry test does not depend on the day
	// it runs.
	Now() time.Time
}

// systemEnv is the production Env: it answers from this process, on this
// machine's network stack.
type systemEnv struct{}

// SystemEnv returns the Env that talks to the real network.
func SystemEnv() Env { return systemEnv{} }

func (systemEnv) Now() time.Time { return time.Now() }

// resolverFor builds a net.Resolver aimed at a specific nameserver, or the
// system one when none is named. The pattern mirrors status/dns_checker.go —
// PreferGo plus a Dial that redirects every query — which is the only way to
// query a chosen server without a DNS library.
func resolverFor(nameserver string) *net.Resolver {
	if nameserver == "" {
		return &net.Resolver{}
	}
	addr := nameserver
	if _, _, err := net.SplitHostPort(addr); err != nil {
		addr = net.JoinHostPort(nameserver, "53")
	}
	return &net.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, _ string) (net.Conn, error) {
			d := net.Dialer{Timeout: resolveTimeout}
			return d.DialContext(ctx, network, addr)
		},
	}
}

func (systemEnv) Resolve(ctx context.Context, host, resolver string) ([]net.IP, error) {
	ctx, cancel := context.WithTimeout(ctx, resolveTimeout)
	defer cancel()

	addrs, err := resolverFor(resolver).LookupIPAddr(ctx, host)
	if err != nil {
		return nil, err
	}
	ips := make([]net.IP, 0, len(addrs))
	for _, a := range addrs {
		ips = append(ips, a.IP)
	}
	return ips, nil
}

func (systemEnv) ReverseLookup(ctx context.Context, ip, resolver string) ([]string, error) {
	ctx, cancel := context.WithTimeout(ctx, resolveTimeout)
	defer cancel()
	return resolverFor(resolver).LookupAddr(ctx, ip)
}

func (systemEnv) Ping(ctx context.Context, host string, count int) (PingStats, error) {
	pinger, err := probing.NewPinger(host)
	if err != nil {
		return PingStats{}, err
	}
	pinger.Count = count
	pinger.Timeout = pingTimeout
	// Windows has no unprivileged ICMP socket: pro-bing's UDP mode silently
	// receives nothing there, which reads as "host down" on a host that is up.
	// Elsewhere unprivileged is right, because DevDesk must not need root.
	pinger.SetPrivileged(runtime.GOOS == "windows")

	if err := pinger.RunWithContext(ctx); err != nil {
		return PingStats{}, err
	}
	s := pinger.Statistics()
	return PingStats{Sent: s.PacketsSent, Received: s.PacketsRecv, AvgRTT: s.AvgRtt}, nil
}

func (systemEnv) DialTCP(ctx context.Context, addr string) (time.Duration, error) {
	ctx, cancel := context.WithTimeout(ctx, dialTimeout)
	defer cancel()

	start := time.Now()
	d := net.Dialer{}
	conn, err := d.DialContext(ctx, "tcp", addr)
	if err != nil {
		return 0, err
	}
	elapsed := time.Since(start)
	_ = conn.Close() //nolint:errcheck // the probe is the dial; a close error says nothing about it
	return elapsed, nil
}

// Handshake deliberately does not verify the chain.
//
// Verification is the tls stage's job, so that it can report *which* part
// failed — untrusted root, missing intermediate, wrong hostname, expired — as
// four separate checks. Letting crypto/tls abort the handshake would collapse
// all four into one error string and lose the certificate we need to inspect,
// which is the defect this package exists to fix: the old check greped the
// leaf and never looked at the chain at all.
func (systemEnv) Handshake(ctx context.Context, addr, serverName string) (*tls.ConnectionState, error) {
	ctx, cancel := context.WithTimeout(ctx, tlsTimeout)
	defer cancel()

	d := tls.Dialer{
		NetDialer: &net.Dialer{},
		Config: &tls.Config{
			InsecureSkipVerify: true, //nolint:gosec // G402: see the doc comment — the tls stage verifies, and must see a bad chain to describe it
			ServerName:         serverName,
			MinVersion:         tls.VersionTLS10, // probing, not securing: report old versions rather than refuse them
		},
	}
	conn, err := d.DialContext(ctx, "tcp", addr)
	if err != nil {
		return nil, err
	}
	defer func() { _ = conn.Close() }()

	tlsConn, ok := conn.(*tls.Conn)
	if !ok {
		return nil, errNotTLSConn
	}
	state := tlsConn.ConnectionState()
	return &state, nil
}

// Head does not verify the chain either, and for a reason worth stating: a
// certificate problem must not hide whether the service answers. "The app
// works, the cert is what is broken" is a useful thing to be told, and the TLS
// checks report the cert problem on rows of their own.
func (systemEnv) Head(ctx context.Context, url string) (HTTPResult, error) {
	ctx, cancel := context.WithTimeout(ctx, httpTimeout)
	defer cancel()

	client := &http.Client{
		Transport: &http.Transport{
			TLSClientConfig: &tls.Config{
				InsecureSkipVerify: true, //nolint:gosec // G402: see the doc comment — chain problems are reported by the tls stage, not by hiding the response
				MinVersion:         tls.VersionTLS10,
			},
		},
		CheckRedirect: func(*http.Request, []*http.Request) error {
			return http.ErrUseLastResponse // the first answer is the observation; a redirect chain is a different question
		},
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodHead, url, nil)
	if err != nil {
		return HTTPResult{}, err
	}
	resp, err := client.Do(req)
	if err != nil {
		return HTTPResult{}, err
	}
	defer func() { _ = resp.Body.Close() }()

	return HTTPResult{
		Status: resp.StatusCode,
		Server: resp.Header.Get("Server"),
		TLS:    resp.TLS != nil,
	}, nil
}

package netcheck

import (
	"context"
	"errors"
)

// errNotTLSConn is returned when a dialer hands back something that is not a
// TLS connection. It cannot happen with tls.Dialer, and is reported rather
// than asserted so a future dialer swap fails loudly.
var errNotTLSConn = errors.New("connection is not a TLS connection")

// checkTitles is the one place a check's human name is written. The skip path
// needs a title for a check that never ran, so it cannot come from the stage
// that would have produced it.
var checkTitles = map[CheckID]string{
	CheckResolve:      "DNS resolution",
	CheckReverseDNS:   "Reverse DNS",
	CheckICMP:         "ICMP echo",
	CheckTCP:          "TCP connect",
	CheckTLSHandshake: "TLS handshake",
	CheckTLSChain:     "Certificate chain",
	CheckTLSHostname:  "Hostname match",
	CheckTLSExpiry:    "Certificate expiry",
	CheckTLSVersion:   "TLS version",
	CheckHTTP:         "HTTP response",
}

// stage is one layer of the pipeline.
type stage struct {
	id        StageID
	dependsOn StageID
	// gate is the check whose verdict decides whether dependent stages run.
	// A stage that gates nothing leaves it empty — which is a decision, not an
	// omission, at both sites that use it.
	gate CheckID
	// produces is what run returns, declared so the skip path can name the
	// checks that never ran. TestEveryStageProducesWhatItDeclares keeps the two
	// in step.
	produces []CheckID
	run      func(ctx context.Context, t Target, env Env, prior *Results) []Check
}

// stages is the pipeline, in order.
//
// Two of the dependencies are worth reading twice:
//
//   - reach gates nothing. ICMP is filtered on a large share of hosts that are
//     perfectly reachable, so a silent ping must not cascade NotApplicable over
//     the TLS checks — which is the whole question the user came to ask.
//   - http depends on connect, not on tls. A broken chain must not hide whether
//     the service answers: "the app works, the certificate is what is wrong" is
//     useful, and the certificate problem has rows of its own.
func stages() []stage {
	return []stage{
		{
			id:       StageResolve,
			gate:     CheckResolve,
			produces: []CheckID{CheckResolve, CheckReverseDNS},
			run:      runResolve,
		},
		{
			id:        StageReach,
			dependsOn: StageResolve,
			produces:  []CheckID{CheckICMP},
			run:       runReach,
		},
		{
			id:        StageConnect,
			dependsOn: StageResolve,
			gate:      CheckTCP,
			produces:  []CheckID{CheckTCP},
			run:       runConnect,
		},
		{
			id:        StageTLS,
			dependsOn: StageConnect,
			produces: []CheckID{
				CheckTLSHandshake, CheckTLSChain,
				CheckTLSHostname, CheckTLSExpiry, CheckTLSVersion,
			},
			run: runTLS,
		},
		{
			id:        StageHTTP,
			dependsOn: StageConnect,
			produces:  []CheckID{CheckHTTP},
			run:       runHTTP,
		},
	}
}

// Run walks the pipeline and returns every check, in order.
//
// A stage whose dependency failed does not run: its checks come back
// NotApplicable carrying the check that blocked them. That is what turns seven
// red rows into one red row and a named point of rupture.
func Run(ctx context.Context, t Target, env Env) (Results, error) {
	var res Results
	if err := t.Validate(); err != nil {
		return res, err
	}

	all := stages()
	gateOf := make(map[StageID]CheckID, len(all))
	for _, s := range all {
		if s.gate != "" {
			gateOf[s.id] = s.gate
		}
	}

	for _, s := range all {
		if ctx.Err() != nil {
			addPlaceholders(&res, s, Unknown, "", "Cancelled before this check ran")
			continue
		}
		if blocker, ok := blockedBy(s, gateOf, res); ok {
			summary := "Skipped — " + checkTitles[blocker] + " did not succeed"
			addPlaceholders(&res, s, NotApplicable, blocker, summary)
			continue
		}
		for _, c := range s.run(ctx, t, env, &res) {
			res.add(c)
		}
	}
	return res, nil
}

// blockedBy reports whether s must be skipped, and which check blocked it.
//
// Only Fail and Unknown block. NotApplicable does not: a target given as a
// literal IP address makes the resolution check NotApplicable, and everything
// below it is perfectly meaningful.
func blockedBy(s stage, gateOf map[StageID]CheckID, res Results) (CheckID, bool) {
	if s.dependsOn == "" {
		return "", false
	}
	gate, ok := gateOf[s.dependsOn]
	if !ok {
		return "", false
	}
	switch res.VerdictOf(gate) {
	case Fail, Unknown:
		return gate, true
	default:
		return "", false
	}
}

// addPlaceholders records the checks a skipped stage would have produced, so a
// question that was never asked is visible as such rather than absent.
func addPlaceholders(res *Results, s stage, v Verdict, because CheckID, summary string) {
	for _, id := range s.produces {
		res.add(Check{
			ID:      id,
			Stage:   s.id,
			Title:   checkTitles[id],
			Verdict: v,
			Summary: summary,
			Because: because,
		})
	}
}

// newCheck starts a check with its declared title, so no stage spells one out.
func newCheck(id CheckID, s StageID, v Verdict, summary string) Check {
	return Check{ID: id, Stage: s, Title: checkTitles[id], Verdict: v, Summary: summary}
}

package netcheck

import (
	"context"
	"fmt"
	"net"
	"strings"
)

// runResolve answers what the target's name maps to, or what its address maps
// back to. Exactly one of the two questions has meaning for a given target,
// and the other says so rather than being absent.
func runResolve(ctx context.Context, t Target, env Env, _ *Results) []Check {
	if ip := net.ParseIP(strings.TrimSpace(t.Host)); ip != nil {
		return []Check{
			literalAddress(ip),
			reverseLookup(ctx, t, env, ip.String()),
		}
	}
	return []Check{
		forwardLookup(ctx, t, env),
		newCheck(CheckReverseDNS, StageResolve, NotApplicable,
			"Target is a name, not an address"),
	}
}

// forwardLookup resolves a name.
func forwardLookup(ctx context.Context, t Target, env Env) Check {
	ips, err := env.Resolve(ctx, t.Host, t.Resolver)
	c := newCheck(CheckResolve, StageResolve, Fail, "")
	c.fact("Resolver", resolverLabel(t.Resolver))

	if err != nil {
		c.Summary = fmt.Sprintf("%s does not resolve", t.Host)
		c.fact("Error", err.Error())
		return c
	}
	if len(ips) == 0 {
		c.Summary = fmt.Sprintf("%s resolves to no address", t.Host)
		return c
	}

	c.Verdict = OK
	if len(ips) == 1 {
		c.Summary = fmt.Sprintf("%s resolves to %s (%s)", t.Host, ips[0], addressClass(ips[0]))
	} else {
		c.Summary = fmt.Sprintf("%s resolves to %d addresses", t.Host, len(ips))
	}
	for _, ip := range ips {
		c.fact("Address", fmt.Sprintf("%s (%s)", ip, addressClass(ip)))
	}
	return c
}

// literalAddress records that no resolution was needed. It is NotApplicable
// with no Because: the question has no meaning here, which is a different
// thing from having been blocked.
func literalAddress(ip net.IP) Check {
	c := newCheck(CheckResolve, StageResolve, NotApplicable,
		"Target is a literal address, no resolution needed")
	c.fact("Address", fmt.Sprintf("%s (%s)", ip, addressClass(ip)))
	return c
}

// reverseLookup asks what an address maps back to.
//
// A missing PTR record is a Warn and never a Fail: plenty of reachable hosts
// have none, and the objective this package serves does not depend on it.
func reverseLookup(ctx context.Context, t Target, env Env, ip string) Check {
	names, err := env.ReverseLookup(ctx, ip, t.Resolver)
	c := newCheck(CheckReverseDNS, StageResolve, Warn, "")
	c.fact("Resolver", resolverLabel(t.Resolver))

	switch {
	case err != nil:
		c.Summary = fmt.Sprintf("%s has no reverse record", ip)
		c.fact("Error", err.Error())
	case len(names) == 0:
		c.Summary = fmt.Sprintf("%s has no reverse record", ip)
	default:
		c.Verdict = OK
		c.Summary = fmt.Sprintf("%s resolves back to %s", ip, strings.TrimSuffix(names[0], "."))
		for _, n := range names {
			c.fact("Name", strings.TrimSuffix(n, "."))
		}
	}
	return c
}

// resolverLabel names the resolver a lookup used. "System resolver" is not a
// placeholder: it is the answer the user cares about, because it is the one
// their own traffic will use.
func resolverLabel(resolver string) string {
	if strings.TrimSpace(resolver) == "" {
		return "System resolver"
	}
	return resolver
}

// addressClass names the family an address belongs to.
//
// The class is what the diagnosis rests on — private or public, routable or
// not — never the literal octets. It is also what survives pseudonymisation if
// a payload is ever built from these checks.
func addressClass(ip net.IP) string {
	switch {
	case ip.IsLoopback():
		return "loopback"
	case ip.IsLinkLocalUnicast(), ip.IsLinkLocalMulticast():
		return "link-local"
	case ip.IsPrivate():
		return "private"
	case ip.IsUnspecified():
		return "unspecified"
	case ip.To4() == nil:
		return "public IPv6"
	default:
		return "public"
	}
}

package netcheck

import (
	"context"
	"fmt"
)

// runReach probes the target with ICMP.
//
// This stage gates nothing, and that is the decision it exists to record: ICMP
// is filtered on a large share of perfectly reachable hosts, so a silent ping
// says little about the host and nothing about its certificate. A no-reply is
// therefore a Warn, never a Fail — the question "is it reachable" is settled by
// the TCP connect, which is the port the user actually named.
func runReach(ctx context.Context, t Target, env Env, _ *Results) []Check {
	stats, err := env.Ping(ctx, t.Host, pingCount)

	// A probe that could not be sent is Unknown, not a failure of the host.
	// On a machine without the privilege to open an ICMP socket, reporting
	// "down" would blame the target for a local restriction.
	if err != nil {
		c := newCheck(CheckICMP, StageReach, Unknown, "ICMP could not be probed")
		c.fact("Error", err.Error())
		return []Check{c}
	}

	c := newCheck(CheckICMP, StageReach, OK, "")
	c.fact("Sent", fmt.Sprintf("%d", stats.Sent))
	c.fact("Received", fmt.Sprintf("%d", stats.Received))

	switch {
	case stats.Received == 0:
		c.Verdict = Warn
		c.Summary = "No ICMP reply — echo may be filtered"
	case stats.Received < stats.Sent:
		c.Verdict = Warn
		c.Summary = fmt.Sprintf("Partial loss: %d of %d replies, %s average",
			stats.Received, stats.Sent, roundedMillis(stats.AvgRTT))
		c.fact("Average RTT", roundedMillis(stats.AvgRTT))
	default:
		c.Summary = fmt.Sprintf("%d of %d replies, %s average",
			stats.Received, stats.Sent, roundedMillis(stats.AvgRTT))
		c.fact("Average RTT", roundedMillis(stats.AvgRTT))
	}
	return []Check{c}
}

package netcheck

import (
	"context"
	"fmt"
)

// runConnect opens a TCP connection to the port the user named.
//
// This is the check that decides reachability, and it is the stage's gate: if
// the port does not answer, there is no handshake to inspect and no response to
// read, so TLS and HTTP come back NotApplicable pointing here rather than
// producing failures of their own about a connection that never existed.
func runConnect(ctx context.Context, t Target, env Env, _ *Results) []Check {
	elapsed, err := env.DialTCP(ctx, t.Addr())

	c := newCheck(CheckTCP, StageConnect, OK, "")
	c.fact("Address", t.Addr())

	if err != nil {
		c.Verdict = Fail
		c.Summary = fmt.Sprintf("Port %d does not accept connections", t.Port)
		c.fact("Error", err.Error())
		return []Check{c}
	}

	c.Summary = fmt.Sprintf("Port %d accepted the connection in %s", t.Port, roundedMillis(elapsed))
	c.fact("Connect time", roundedMillis(elapsed))
	return []Check{c}
}

package netcheck

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"errors"
	"fmt"
	"math"
	"time"
)

// runTLS completes a handshake and then asks four separate questions of what
// came back: does the chain verify, is it valid for this name, when does it
// expire, and which protocol version was negotiated.
//
// The handshake is deliberately unverified (see systemEnv.Handshake). That is
// what makes the four questions separable: crypto/tls aborting on an untrusted
// root would collapse all of them into one error string and take the
// certificate with it. The check this replaces greped the leaf's text and never
// looked at the chain at all.
func runTLS(ctx context.Context, t Target, env Env, _ *Results) []Check {
	state, err := env.Handshake(ctx, t.Addr(), t.Host)
	if err != nil {
		return handshakeFailed(t, err)
	}
	if len(state.PeerCertificates) == 0 {
		hs := newCheck(CheckTLSHandshake, StageTLS, Unknown, "Handshake completed but no certificate was presented")
		return append([]Check{hs}, dependentsOf(CheckTLSHandshake, "Skipped — no certificate to inspect")...)
	}

	leaf := state.PeerCertificates[0]
	now := env.Now()

	hs := newCheck(CheckTLSHandshake, StageTLS, OK,
		fmt.Sprintf("Handshake completed, %d certificate(s) presented", len(state.PeerCertificates)))
	hs.fact("Negotiated version", tlsVersionName(state.Version))
	hs.fact("Subject", leaf.Subject.CommonName)
	hs.fact("Issuer", leaf.Issuer.CommonName)

	expiry := expiryCheck(leaf, now)

	return []Check{
		hs,
		chainCheck(state, now, expiry.Verdict),
		hostnameCheck(leaf, t.Host),
		expiry,
		versionCheck(state.Version),
	}
}

// handshakeFailed tells "this port does not speak TLS" apart from "TLS is
// broken here", because they are different answers and only one is a problem.
//
// The signal is crypto/tls's own: a server that answers with something that is
// not a TLS record produces a RecordHeaderError. That is an observation, not a
// guess from the port number — which matters, since guessing from the port is
// exactly the heuristic §3.8 settled against elsewhere.
//
// The limit, stated rather than discovered: a server that closes the connection
// without answering at all is indistinguishable from a broken TLS endpoint, and
// is reported as a failure.
func handshakeFailed(t Target, err error) []Check {
	var rhe tls.RecordHeaderError
	if errors.As(err, &rhe) {
		c := newCheck(CheckTLSHandshake, StageTLS, NotApplicable,
			fmt.Sprintf("Port %d does not speak TLS", t.Port))
		return append([]Check{c}, dependentsOf("", "Port does not speak TLS")...)
	}

	c := newCheck(CheckTLSHandshake, StageTLS, Fail, "TLS handshake failed")
	c.fact("Error", err.Error())
	return append([]Check{c}, dependentsOf(CheckTLSHandshake, "Skipped — the handshake did not complete")...)
}

// dependentsOf marks the four certificate checks as unanswerable. `because` is
// empty when the port simply does not speak TLS: nothing failed, so nothing is
// blaming anything.
func dependentsOf(because CheckID, summary string) []Check {
	ids := []CheckID{CheckTLSChain, CheckTLSHostname, CheckTLSExpiry, CheckTLSVersion}
	out := make([]Check, 0, len(ids))
	for _, id := range ids {
		c := newCheck(id, StageTLS, NotApplicable, summary)
		c.Because = because
		out = append(out, c)
	}
	return out
}

// chainCheck verifies the leaf against the system trust store, using only the
// intermediates the server actually sent.
//
// Two things are reported that the old check could not see at all:
//
//   - whether the chain verifies, and why it does not — an unknown authority
//     and an incomplete chain are different problems with different fixes.
//   - whether the server sent its intermediates, *independently of whether
//     verification succeeded*. A chain the local platform completes for itself
//     still breaks on clients that do not, so it is a Warn rather than a pass.
//
// An expired certificate makes verification fail for a reason the expiry check
// already reports, so the chain comes back NotApplicable pointing at it rather
// than saying the same thing twice.
func chainCheck(state *tls.ConnectionState, now time.Time, expiryVerdict Verdict) Check {
	leaf := state.PeerCertificates[0]
	intermediates := x509.NewCertPool()
	for _, cert := range state.PeerCertificates[1:] {
		intermediates.AddCert(cert)
	}

	c := newCheck(CheckTLSChain, StageTLS, OK, "")
	c.fact("Certificates presented", fmt.Sprintf("%d", len(state.PeerCertificates)))
	for _, cert := range state.PeerCertificates[1:] {
		c.fact("Intermediate", cert.Subject.CommonName)
	}

	if expiryVerdict == Fail {
		c.Verdict = NotApplicable
		c.Because = CheckTLSExpiry
		c.Summary = "Not verified — the certificate is expired"
		return c
	}

	_, err := leaf.Verify(x509.VerifyOptions{
		Intermediates: intermediates,
		CurrentTime:   now,
	})

	selfSigned := len(state.PeerCertificates) == 1 && leaf.CheckSignatureFrom(leaf) == nil

	switch {
	case err != nil && selfSigned:
		c.Verdict = Fail
		c.Summary = "Certificate is self-signed and not trusted"
		c.fact("Error", err.Error())
	case err != nil && len(state.PeerCertificates) == 1:
		c.Verdict = Fail
		c.Summary = "Chain does not verify — the server sent no intermediate certificates"
		c.fact("Error", err.Error())
	case err != nil:
		c.Verdict = Fail
		c.Summary = "Chain does not verify against the system trust store"
		c.fact("Error", err.Error())
	case len(state.PeerCertificates) == 1 && !selfSigned:
		c.Verdict = Warn
		c.Summary = "Chain verifies here, but the server sent no intermediates — other clients may fail"
	default:
		c.Summary = fmt.Sprintf("Chain verifies against the system trust store (%d certificate(s))",
			len(state.PeerCertificates))
	}
	return c
}

// hostnameCheck asks whether the certificate is valid for the name that was
// dialled. It is separate from the chain on purpose: a perfectly trusted
// certificate for the wrong name and an untrusted certificate for the right one
// are different problems, and the old check reported neither.
func hostnameCheck(leaf *x509.Certificate, host string) Check {
	c := newCheck(CheckTLSHostname, StageTLS, OK, "")
	for _, name := range leaf.DNSNames {
		c.fact("SAN", name)
	}
	for _, ip := range leaf.IPAddresses {
		c.fact("SAN", ip.String())
	}

	if err := leaf.VerifyHostname(host); err != nil {
		c.Verdict = Fail
		c.Summary = fmt.Sprintf("Certificate is not valid for %s", host)
		c.fact("Error", err.Error())
		return c
	}
	c.Summary = fmt.Sprintf("Certificate is valid for %s", host)
	return c
}

// expiryCheck reports the validity window in days, which is the unit the
// decision is actually made in.
func expiryCheck(leaf *x509.Certificate, now time.Time) Check {
	c := newCheck(CheckTLSExpiry, StageTLS, OK, "")
	c.fact("Not before", leaf.NotBefore.UTC().Format(time.RFC3339))
	c.fact("Not after", leaf.NotAfter.UTC().Format(time.RFC3339))

	switch {
	case now.Before(leaf.NotBefore):
		c.Verdict = Fail
		c.Summary = fmt.Sprintf("Certificate is not valid until %s (in %s)",
			leaf.NotBefore.UTC().Format(time.DateOnly), inDays(leaf.NotBefore.Sub(now)))
	case now.After(leaf.NotAfter):
		c.Verdict = Fail
		c.Summary = fmt.Sprintf("Certificate expired %s ago, on %s",
			inDays(now.Sub(leaf.NotAfter)), leaf.NotAfter.UTC().Format(time.DateOnly))
	case leaf.NotAfter.Sub(now) < expiryWarnWindow:
		c.Verdict = Warn
		c.Summary = fmt.Sprintf("Certificate expires in %s, on %s",
			inDays(leaf.NotAfter.Sub(now)), leaf.NotAfter.UTC().Format(time.DateOnly))
	default:
		c.Summary = fmt.Sprintf("Certificate is valid for another %s, until %s",
			inDays(leaf.NotAfter.Sub(now)), leaf.NotAfter.UTC().Format(time.DateOnly))
	}
	return c
}

// versionCheck reports the negotiated protocol version. TLS 1.0 and 1.1 are a
// Warn and not a Fail: the connection works, which is what Fail is reserved
// for, and both are deprecated rather than broken.
func versionCheck(version uint16) Check {
	name := tlsVersionName(version)
	c := newCheck(CheckTLSVersion, StageTLS, OK, "Negotiated "+name)
	c.fact("Version", name)
	if version < tls.VersionTLS12 {
		c.Verdict = Warn
		c.Summary = "Negotiated " + name + ", which is deprecated"
	}
	return c
}

func tlsVersionName(v uint16) string {
	switch v {
	case tls.VersionTLS10:
		return "TLS 1.0"
	case tls.VersionTLS11:
		return "TLS 1.1"
	case tls.VersionTLS12:
		return "TLS 1.2"
	case tls.VersionTLS13:
		return "TLS 1.3"
	default:
		return fmt.Sprintf("unknown (0x%04x)", v)
	}
}

// inDays renders a duration in whole days, the unit certificate decisions are
// made in. Under a day it says so rather than rounding to zero, which would
// read as "expires today" on something with hours left.
func inDays(d time.Duration) string {
	days := int(math.Floor(d.Hours() / 24))
	switch {
	case days < 1:
		return "less than a day"
	case days == 1:
		return "1 day"
	default:
		return fmt.Sprintf("%d days", days)
	}
}

package netcheck

import (
	"context"
	"fmt"
	"net"
	"net/url"
	"strconv"
)

// runHTTP asks whether the service answers.
//
// The scheme comes from what the handshake observed, not from the port number.
// That is the defect this replaces: RunCurl chose HTTPS only when the port was
// literally 443, so a service on :8443 was probed in the clear, failed, and
// read as "the host is down".
//
// The stage depends on connect rather than on tls, which is deliberate: a
// broken certificate must not hide whether the application responds. "It works,
// the certificate is what is wrong" is a useful thing to be told, and the
// certificate problem has four rows of its own.
func runHTTP(ctx context.Context, t Target, env Env, prior *Results) []Check {
	scheme := "http"
	if prior.VerdictOf(CheckTLSHandshake) == OK {
		scheme = "https"
	}
	target := (&url.URL{
		Scheme: scheme,
		Host:   net.JoinHostPort(t.Host, strconv.Itoa(t.Port)),
		Path:   "/",
	}).String()

	res, err := env.Head(ctx, target)

	c := newCheck(CheckHTTP, StageHTTP, OK, "")
	c.fact("URL", target)

	if err != nil {
		c.Verdict = Fail
		c.Summary = fmt.Sprintf("No HTTP response over %s", scheme)
		c.fact("Error", err.Error())
		return []Check{c}
	}

	c.fact("Status", strconv.Itoa(res.Status))
	c.fact("Server", res.Server)

	switch {
	case res.Status >= 500:
		c.Verdict = Fail
		c.Summary = fmt.Sprintf("Server error: HTTP %d", res.Status)
	case res.Status >= 400:
		// The service answered, which is what this check asks. 401 and 403 are
		// a working endpoint declining an unauthenticated HEAD, and calling
		// that a failure would be wrong far more often than right.
		c.Verdict = Warn
		c.Summary = fmt.Sprintf("Service answered with HTTP %d", res.Status)
	default:
		c.Summary = fmt.Sprintf("Service answered with HTTP %d over %s", res.Status, scheme)
	}
	return []Check{c}
}

package netcheck

import (
	"fmt"
	"time"
)

// roundedMillis renders a latency the way a diagnostic reads it: whole
// milliseconds above 1 ms, and a sub-millisecond figure below, because "0 ms"
// on a loopback connection looks like a missing measurement rather than a fast
// one.
func roundedMillis(d time.Duration) string {
	if d <= 0 {
		return "0 ms"
	}
	if d < time.Millisecond {
		return fmt.Sprintf("%.2f ms", float64(d.Microseconds())/1000)
	}
	return fmt.Sprintf("%d ms", d.Round(time.Millisecond).Milliseconds())
}

